-- Gathering nodes and treasure chests left at their pre-Cataclysm heights in the old-world zones that Cataclysm reshaped
-- (Silverpine, Darkshore, Azshara, Stonetalon, Badlands, Thousand Needles, Tanaris and others), found by comparing each
-- spawn's z with the 5.4.8 terrain and vmap model surfaces under it. Cataclysm's own zones (Hyjal, Vashj'ir, Uldum,
-- Twilight Highlands) are left alone.

-- Spawns 0.5 to 20 yards off the ground: put them on the nearest open floor (terrain, or a model such as a mine floor)
DROP TEMPORARY TABLE IF EXISTS `_gameobject_ground_z`;
CREATE TEMPORARY TABLE `_gameobject_ground_z` (
    `guid` INT UNSIGNED NOT NULL,
    `id` MEDIUMINT UNSIGNED NOT NULL,
    `position_z` FLOAT NOT NULL,
    PRIMARY KEY (`guid`)
) ENGINE=InnoDB;


UPDATE `gameobject` g JOIN `_gameobject_ground_z` n ON n.`guid` = g.`guid` AND n.`id` = g.`id` SET g.`position_z` = n.`position_z`;
DROP TEMPORARY TABLE `_gameobject_ground_z`;

-- Spawns whose spot no longer exists: more than 20 yards above or inside the new ground, or now deep under water
DROP TEMPORARY TABLE IF EXISTS `_gameobject_removed`;
CREATE TEMPORARY TABLE `_gameobject_removed` (
    `guid` INT UNSIGNED NOT NULL,
    `id` MEDIUMINT UNSIGNED NOT NULL,
    PRIMARY KEY (`guid`)
) ENGINE=InnoDB;


DELETE p FROM `pool_gameobject` p JOIN `gameobject` g ON g.`guid` = p.`guid` JOIN `_gameobject_removed` r ON r.`guid` = g.`guid` AND r.`id` = g.`id`;
DELETE g FROM `gameobject` g JOIN `_gameobject_removed` r ON r.`guid` = g.`guid` AND r.`id` = g.`id`;
DROP TEMPORARY TABLE `_gameobject_removed`;

-- Their node pools that are left without members
DROP TEMPORARY TABLE IF EXISTS `_pool_removed`;
CREATE TEMPORARY TABLE `_pool_removed` (`entry` INT UNSIGNED NOT NULL, PRIMARY KEY (`entry`)) ENGINE=InnoDB;

DELETE r FROM `_pool_removed` r WHERE EXISTS (SELECT 1 FROM `pool_gameobject` WHERE `pool_entry` = r.`entry`)
    OR EXISTS (SELECT 1 FROM `pool_creature` WHERE `pool_entry` = r.`entry`)
    OR EXISTS (SELECT 1 FROM `pool_quest` WHERE `pool_entry` = r.`entry`);
DELETE p FROM `pool_pool` p JOIN `_pool_removed` r ON r.`entry` = p.`pool_id`;
DELETE t FROM `pool_template` t JOIN `_pool_removed` r ON r.`entry` = t.`entry`;
DROP TEMPORARY TABLE `_pool_removed`;
